    for col in sorted(set(x for r in g for x in r if x)):
        cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==col]
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        res[col]=(min(rs),max(rs),min(cs),max(cs),len(cells))
    return res
